import{_ as o,o as a,c as i,ag as t}from"./chunks/framework.DWOJQht4.js";const r="/CloudCTF/images/competition_detail.png",e="/CloudCTF/images/vuln-lab-list.png",q=JSON.parse('{"title":"管理员指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/admin-guide.md","filePath":"guide/admin-guide.md","lastUpdated":1792636228000}'),s={name:"guide/admin-guide.md"};function n(h,l,d,u,c,g){return a(),i("div",null,[...l[0]||(l[0]=[t('<h1 id="管理员指南" tabindex="-1">管理员指南 <a class="header-anchor" href="#管理员指南" aria-label="Permalink to &quot;管理员指南&quot;">​</a></h1><p>本指南面向 CloudCTF 平台的管理员，介绍如何使用管理后台进行平台管理、题目管理、比赛管理等操作。</p><h2 id="登录管理后台" tabindex="-1">登录管理后台 <a class="header-anchor" href="#登录管理后台" aria-label="Permalink to &quot;登录管理后台&quot;">​</a></h2><h3 id="访问地址" tabindex="-1">访问地址 <a class="header-anchor" href="#访问地址" aria-label="Permalink to &quot;访问地址&quot;">​</a></h3><p>管理后台地址：<code>http://your-domain/admin</code></p><h3 id="默认账号" tabindex="-1">默认账号 <a class="header-anchor" href="#默认账号" aria-label="Permalink to &quot;默认账号&quot;">​</a></h3><p>首次部署后，使用以下默认账号登录：</p><ul><li><strong>用户名</strong>：<code>admin</code></li><li><strong>密码</strong>：首次运行时随机生成，保存在 <code>data/.env</code> 的 <code>FIRST_SUPERUSER_PASSWORD</code> 中</li></ul><p>在 CloudCTF 工作目录执行以下命令查看首次登录密码：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;^FIRST_SUPERUSER_PASSWORD=&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/.env</span></span></code></pre></div><p>如果通过 <code>CONFIG_FILE</code> 指定了其他配置文件，请从对应文件读取。该密码只用于首次创建管理员；修改配置文件不会重置已经存在的管理员密码，忘记密码时请使用 CLI 重置命令。</p><div class="info custom-block"><p class="custom-block-title">部署说明</p><p>当前平台主服务的官方部署方式是 <strong>单二进制运行</strong>。<br> 管理员指南中提到的 Docker、Compose、模板、多服务编排，都是指 <strong>题目运行环境 / 漏洞环境模板能力</strong>，不是指平台主服务通过 <code>docker-compose</code> 部署。</p></div><div class="warning custom-block"><p class="custom-block-title">安全提示</p><p>首次登录后，请立即修改随机初始密码！</p></div><h2 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to &quot;用户管理&quot;">​</a></h2><h3 id="查看用户列表" tabindex="-1">查看用户列表 <a class="header-anchor" href="#查看用户列表" aria-label="Permalink to &quot;查看用户列表&quot;">​</a></h3><ol><li>登录管理后台</li><li>点击左侧菜单 <strong>用户管理</strong> → <strong>用户列表</strong></li><li>可以查看所有注册用户的信息</li></ol><h3 id="用户操作" tabindex="-1">用户操作 <a class="header-anchor" href="#用户操作" aria-label="Permalink to &quot;用户操作&quot;">​</a></h3><ul><li><strong>编辑用户</strong>：点击操作列的&quot;编辑&quot;按钮，可以修改用户信息</li><li><strong>禁用用户</strong>：点击&quot;禁用&quot;按钮，禁止用户登录</li><li><strong>删除用户</strong>：点击&quot;删除&quot;按钮，永久删除用户（谨慎操作）</li><li><strong>重置密码</strong>：点击&quot;重置密码&quot;按钮，为用户生成新密码</li></ul><h3 id="队伍管理" tabindex="-1">队伍管理 <a class="header-anchor" href="#队伍管理" aria-label="Permalink to &quot;队伍管理&quot;">​</a></h3><p>队伍用于组织参赛成员参与比赛（尤其是团队赛/攻防赛等）。</p><h4 id="查看队伍列表" tabindex="-1">查看队伍列表 <a class="header-anchor" href="#查看队伍列表" aria-label="Permalink to &quot;查看队伍列表&quot;">​</a></h4><ol><li>进入 <strong>用户管理</strong> → <strong>队伍管理</strong></li><li>查看队伍信息（队伍名称、队长、成员数量、创建时间等）</li></ol><h4 id="队伍操作" tabindex="-1">队伍操作 <a class="header-anchor" href="#队伍操作" aria-label="Permalink to &quot;队伍操作&quot;">​</a></h4><ul><li><strong>查看队伍详情</strong>：查看队伍成员、队伍信息</li><li><strong>编辑队伍</strong>：修改队伍名称、描述等信息</li><li><strong>解散/删除队伍</strong>：谨慎操作，可能影响比赛参与数据</li></ul><h4 id="批量导入队伍" tabindex="-1">批量导入队伍 <a class="header-anchor" href="#批量导入队伍" aria-label="Permalink to &quot;批量导入队伍&quot;">​</a></h4><p>当需要为学校/企业/活动快速初始化大量队伍时，可以使用批量导入。</p><ol><li>进入 <strong>用户管理</strong> → <strong>队伍管理</strong></li><li>点击&quot;批量导入&quot;按钮</li><li>按模板准备导入文件（通常为 CSV/Excel，字段以页面提示为准）</li><li>上传并确认导入结果</li></ol><div class="tip custom-block"><p class="custom-block-title">提示</p><p>批量导入前建议先导出一份示例模板，在示例基础上填充数据，避免字段不匹配导致导入失败。</p></div><h2 id="赛事管理" tabindex="-1">赛事管理 <a class="header-anchor" href="#赛事管理" aria-label="Permalink to &quot;赛事管理&quot;">​</a></h2><p>赛事管理用于创建比赛、配置赛制与题目、管理参赛权限与数据导出等。</p><h3 id="比赛类型" tabindex="-1">比赛类型 <a class="header-anchor" href="#比赛类型" aria-label="Permalink to &quot;比赛类型&quot;">​</a></h3><h4 id="_1-理论赛" tabindex="-1">1. 理论赛 <a class="header-anchor" href="#_1-理论赛" aria-label="Permalink to &quot;1. 理论赛&quot;">​</a></h4><p>选择题、填空题等理论知识考核。</p><ul><li><strong>题目类型</strong>：单选、多选、填空、简答</li><li><strong>自动评分</strong>：系统自动判分</li><li><strong>限时答题</strong>：可设置答题时间限制</li></ul><h4 id="_2-解题赛-ctf" tabindex="-1">2. 解题赛（CTF） <a class="header-anchor" href="#_2-解题赛-ctf" aria-label="Permalink to &quot;2. 解题赛（CTF）&quot;">​</a></h4><p>传统的 CTF 解题模式，用户通过解题获得分数。</p><ul><li><strong>计分方式</strong>：固定分值 / 动态分值</li><li><strong>排行榜</strong>：实时更新</li><li><strong>一血奖励</strong>：首个解出题目的用户额外加分</li><li><strong>题目类型</strong>：Web / Pwn / Reverse / Crypto / Misc / Mobile</li><li><strong>环境类型</strong> 静态题目/容器化</li></ul><h4 id="_3-攻防赛-awd" tabindex="-1">3. 攻防赛（AWD） <a class="header-anchor" href="#_3-攻防赛-awd" aria-label="Permalink to &quot;3. 攻防赛（AWD）&quot;">​</a></h4><p>攻防兼备的比赛模式，每个队伍维护自己的靶机，同时攻击其他队伍。</p><ul><li><strong>靶机分配</strong>：自动为每个队伍分配靶机</li><li><strong>Flag 轮转</strong>：定时更换 Flag</li><li><strong>攻击检测</strong>：记录攻击日志</li><li><strong>防御检测</strong>：检查服务可用性</li></ul><h3 id="创建比赛" tabindex="-1">创建比赛 <a class="header-anchor" href="#创建比赛" aria-label="Permalink to &quot;创建比赛&quot;">​</a></h3><ol><li>进入 <strong>比赛管理</strong> → <strong>比赛列表</strong></li><li>点击&quot;新建比赛&quot;按钮</li><li>填写比赛信息： <ul><li><strong>比赛名称</strong>：比赛标题</li><li><strong>比赛描述</strong>：比赛说明（支持 Markdown）</li><li><strong>开始时间</strong>：比赛开始时间</li><li><strong>结束时间</strong>：比赛结束时间</li><li><strong>参赛模式</strong>： 个人赛/团体赛</li><li><strong>比赛类型</strong>：解题赛 / 攻防赛 / 理论赛 / 混合</li><li><strong>是否公开</strong>：是否允许所有用户参加</li><li><strong>开放注册</strong>：是否允许访客加入(需要审核)</li></ul></li><li>点击&quot;提交&quot;保存</li></ol><h3 id="赛事详情" tabindex="-1">赛事详情 <a class="header-anchor" href="#赛事详情" aria-label="Permalink to &quot;赛事详情&quot;">​</a></h3><p>创建比赛后，进入比赛详情页可对赛事进行日常管理，包括公告、关卡、成绩单、参赛单位、WP、管理员等。</p><p><img src="'+r+`" alt="赛事详情页"></p><h4 id="公告" tabindex="-1">公告 <a class="header-anchor" href="#公告" aria-label="Permalink to &quot;公告&quot;">​</a></h4><p>用于向参赛者发布赛事相关通知（例如赛程说明、环境变更、已知问题、临时规则等）。</p><ol><li>进入比赛详情页 → <strong>公告</strong></li><li>点击&quot;新建公告&quot;</li><li>填写公告标题与内容</li><li>选择是否置顶/是否立即发布（以页面为准）</li><li>保存后公告会展示在选手侧赛事页面</li></ol><h4 id="关卡" tabindex="-1">关卡 <a class="header-anchor" href="#关卡" aria-label="Permalink to &quot;关卡&quot;">​</a></h4><p>用于组织赛事的阶段/关卡结构（例如初赛/复赛、阶段一/阶段二、不同题目集等）。</p><ol><li>进入比赛详情页 → <strong>关卡</strong></li><li>点击&quot;新建关卡&quot;</li><li>配置关卡名称、开放时间/关闭时间、排序等</li><li>在关卡内添加题目或调整题目顺序（以页面为准）</li></ol><h5 id="动态环境与模板选择" tabindex="-1">动态环境与模板选择 <a class="header-anchor" href="#动态环境与模板选择" aria-label="Permalink to &quot;动态环境与模板选择&quot;">​</a></h5><p>关卡中通常会包含不同类型的题目：</p><ul><li><strong>静态题目</strong>：无需启动环境，直接在题目中配置 Flag 与附件即可</li><li><strong>动态环境题目</strong>：需要为参赛者启动独立容器环境（例如 Web 靶机、漏洞复现环境等）</li></ul><p>当关卡内包含动态环境题目时，需要先准备好对应的环境模板：</p><ol><li>在题目中选择/绑定对应的容器模板或漏洞环境模板（以页面为准）</li><li>将题目加入到关卡后，参赛者在比赛页面可按题目启动靶机</li></ol><p>容器模板的创建与配置请参考：<a href="/CloudCTF/guide/admin-guide.html#容器模板管理">容器模板管理</a></p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>建议先完成“虚拟化环境配置”，并至少创建 1 个可正常启动的容器模板，再进行关卡与动态题目编排。</p></div><div class="tip custom-block"><p class="custom-block-title">提示</p><p>如果比赛类型为混合赛制，建议通过关卡划分不同模块，方便参赛者理解与组织。</p></div><h4 id="成绩单" tabindex="-1">成绩单 <a class="header-anchor" href="#成绩单" aria-label="Permalink to &quot;成绩单&quot;">​</a></h4><p>用于查看与导出比赛结果数据（排行榜、提交记录、各题解题情况等）。</p><ol><li>进入比赛详情页 → <strong>成绩单</strong></li><li>查看实时排行榜与统计</li><li>如需留档，可导出数据（CSV/Excel 等，以页面为准）</li></ol><h4 id="参赛单位" tabindex="-1">参赛单位 <a class="header-anchor" href="#参赛单位" aria-label="Permalink to &quot;参赛单位&quot;">​</a></h4><p>用于管理参赛单位/组织（例如学校、班级、企业部门等），常用于团体赛报名与统计。</p><ol><li>进入比赛详情页 → <strong>参赛单位</strong></li><li>新建参赛单位或编辑单位信息</li><li>为单位绑定参赛队伍/成员（以页面为准）</li></ol><h4 id="wp" tabindex="-1">WP <a class="header-anchor" href="#wp" aria-label="Permalink to &quot;WP&quot;">​</a></h4><p>用于收集与管理参赛者提交的 WriteUp（题解/复盘）。</p><ol><li>进入比赛详情页 → <strong>WP</strong></li><li>查看提交列表</li><li>审核/发布/导出（以页面为准）</li></ol><h4 id="管理员" tabindex="-1">管理员 <a class="header-anchor" href="#管理员" aria-label="Permalink to &quot;管理员&quot;">​</a></h4><p>用于给比赛分配管理人员，支持按比赛维度授权（例如只允许管理自己负责的比赛）。</p><ol><li>进入比赛详情页 → <strong>管理员</strong></li><li>添加管理员用户</li><li>保存后该管理员可在后台看到并管理该比赛</li></ol><h3 id="添加题目到比赛" tabindex="-1">添加题目到比赛 <a class="header-anchor" href="#添加题目到比赛" aria-label="Permalink to &quot;添加题目到比赛&quot;">​</a></h3><ol><li>编辑比赛</li><li>在&quot;题目列表&quot;部分，点击&quot;添加题目&quot;</li><li>选择要添加的题目</li><li>配置题目在比赛中的分值（可选）</li><li>保存</li></ol><h3 id="比赛权限管理" tabindex="-1">比赛权限管理 <a class="header-anchor" href="#比赛权限管理" aria-label="Permalink to &quot;比赛权限管理&quot;">​</a></h3><h4 id="公开比赛" tabindex="-1">公开比赛 <a class="header-anchor" href="#公开比赛" aria-label="Permalink to &quot;公开比赛&quot;">​</a></h4><p>所有注册用户都可以参加。</p><h4 id="邀请制比赛" tabindex="-1">邀请制比赛 <a class="header-anchor" href="#邀请制比赛" aria-label="Permalink to &quot;邀请制比赛&quot;">​</a></h4><ol><li>创建比赛时，取消勾选&quot;公开比赛&quot;</li><li>进入比赛详情页</li><li>点击&quot;邀请用户&quot;按钮</li><li>选择要邀请的用户或团队</li><li>发送邀请</li></ol><h3 id="比赛监控" tabindex="-1">比赛监控 <a class="header-anchor" href="#比赛监控" aria-label="Permalink to &quot;比赛监控&quot;">​</a></h3><ol><li>进入比赛详情页</li><li>查看实时数据： <ul><li><strong>参赛人数</strong>：当前参赛用户数</li><li><strong>解题情况</strong>：各题目的解题人数</li><li><strong>排行榜</strong>：实时排名</li><li><strong>提交记录</strong>：所有 Flag 提交记录</li></ul></li></ol><h3 id="比赛结束后" tabindex="-1">比赛结束后 <a class="header-anchor" href="#比赛结束后" aria-label="Permalink to &quot;比赛结束后&quot;">​</a></h3><ol><li>比赛自动结束，用户无法继续提交</li><li>导出比赛数据： <ul><li><strong>排行榜</strong>：导出为 CSV 或 Excel</li><li><strong>解题记录</strong>：导出所有提交记录</li><li><strong>WriteUp</strong>：收集参赛者的题解</li></ul></li></ol><h2 id="理论题管理" tabindex="-1">理论题管理 <a class="header-anchor" href="#理论题管理" aria-label="Permalink to &quot;理论题管理&quot;">​</a></h2><p>理论题管理用于维护平台的理论题题库，并为&quot;理论赛&quot;提供可复用的题目来源。通过理论题管理，你可以统一管理题干、选项、正确答案、解析与分值，并在赛事中快速组卷与发布。</p><p>同时，理论题管理还提供了配套的数据能力：</p><ul><li><strong>成绩单</strong>：查看参赛者提交记录与判分结果</li><li><strong>统计分析</strong>：查看题目正确率、选项分布、答题耗时等，用于赛后复盘与题库优化</li></ul><h3 id="理论题类型" tabindex="-1">理论题类型 <a class="header-anchor" href="#理论题类型" aria-label="Permalink to &quot;理论题类型&quot;">​</a></h3><p>理论题用于理论赛的题库建设与考试组织。</p><ul><li><strong>单选题</strong>：从多个选项中选择唯一正确答案</li><li><strong>多选题</strong>：从多个选项中选择一个或多个正确答案</li><li><strong>填空题</strong>：填写简短文本作为答案</li><li><strong>简答题</strong>：提交较长文本（通常需要人工或规则辅助评阅）</li></ul><h3 id="创建理论题" tabindex="-1">创建理论题 <a class="header-anchor" href="#创建理论题" aria-label="Permalink to &quot;创建理论题&quot;">​</a></h3><h4 id="_1-新建题目" tabindex="-1">1. 新建题目 <a class="header-anchor" href="#_1-新建题目" aria-label="Permalink to &quot;1. 新建题目&quot;">​</a></h4><ol><li>进入 <strong>理论题管理</strong> → <strong>理论题列表</strong></li><li>点击&quot;新建&quot;按钮</li><li>选择题型并填写题干、选项与答案（以页面为准）</li><li>设置分值、解析（可选）</li><li>保存后即可在理论赛中引用该题</li></ol><h3 id="成绩单与统计" tabindex="-1">成绩单与统计 <a class="header-anchor" href="#成绩单与统计" aria-label="Permalink to &quot;成绩单与统计&quot;">​</a></h3><p>理论题的提交记录与统计通常在：</p><ul><li><strong>理论题管理</strong> → <strong>成绩单</strong>：查看理论赛提交与评分结果</li><li><strong>理论题管理</strong> → <strong>统计分析</strong>：查看题目正确率、答题分布等</li></ul><h2 id="ctf练兵场" tabindex="-1">CTF练兵场 <a class="header-anchor" href="#ctf练兵场" aria-label="Permalink to &quot;CTF练兵场&quot;">​</a></h2><p>CTF练兵场用于日常训练与题库运营。管理员可以在这里维护 CTF 关卡（题目），并支持静态题目与容器化题目两种形态。</p><h3 id="ctf关卡列表" tabindex="-1">CTF关卡列表 <a class="header-anchor" href="#ctf关卡列表" aria-label="Permalink to &quot;CTF关卡列表&quot;">​</a></h3><ol><li>进入 <strong>CTF练兵场</strong> → <strong>CTF关卡列表</strong></li><li>查看关卡状态（草稿/发布/隐藏等，以页面为准）、分类、分值与创建时间</li></ol><h3 id="创建ctf关卡" tabindex="-1">创建CTF关卡 <a class="header-anchor" href="#创建ctf关卡" aria-label="Permalink to &quot;创建CTF关卡&quot;">​</a></h3><ol><li>进入 <strong>CTF练兵场</strong> → <strong>CTF关卡列表</strong></li><li>点击&quot;创建CTF关卡&quot;按钮</li><li>填写题目基础信息（名称、分类、描述、分值等）</li><li>选择环境类型： <ul><li><strong>静态题目</strong>：直接配置 Flag 与附件</li><li><strong>容器化题目</strong>：为每个参赛者启动独立环境</li></ul></li><li>点击&quot;提交&quot;保存</li></ol><h3 id="容器化题目-动态环境" tabindex="-1">容器化题目（动态环境） <a class="header-anchor" href="#容器化题目-动态环境" aria-label="Permalink to &quot;容器化题目（动态环境）&quot;">​</a></h3><p>当题目选择&quot;容器化&quot;时，需要绑定容器模板：</p><ol><li>在题目编辑页的&quot;容器配置&quot;中选择容器模板</li><li>配置容器参数（如生存时间、最大实例数等，以页面为准）</li><li>保存后，选手侧可通过&quot;启动靶机&quot;进入题目环境</li></ol><p>容器模板的创建与配置请参考：<a href="/CloudCTF/guide/admin-guide.html#容器模板管理">容器模板管理</a></p><h3 id="容器实例" tabindex="-1">容器实例 <a class="header-anchor" href="#容器实例" aria-label="Permalink to &quot;容器实例&quot;">​</a></h3><p>容器化题目运行后，会产生容器实例，可用于排障与运维：</p><ol><li>进入 <strong>CTF练兵场</strong> → <strong>容器实例</strong>（或 <strong>虚拟化管理</strong> → <strong>容器实例</strong>，以页面为准）</li><li>查看实例状态、端口映射与运行日志</li><li>必要时可重启或停止实例（谨慎操作）</li></ol><h2 id="动态靶场管理" tabindex="-1">动态靶场管理 <a class="header-anchor" href="#动态靶场管理" aria-label="Permalink to &quot;动态靶场管理&quot;">​</a></h2><h3 id="容器模板管理" tabindex="-1">容器模板管理 <a class="header-anchor" href="#容器模板管理" aria-label="Permalink to &quot;容器模板管理&quot;">​</a></h3><p>CloudCTF 支持基于 Docker 的动态靶场，可以为每个用户启动独立的靶机环境。</p><h4 id="创建容器模板" tabindex="-1">创建容器模板 <a class="header-anchor" href="#创建容器模板" aria-label="Permalink to &quot;创建容器模板&quot;">​</a></h4><ol><li>进入 <strong>虚拟化管理</strong> → <strong>容器模板</strong></li><li>点击&quot;新建模板&quot;按钮</li><li>填写模板信息： <ul><li><strong>模板名称</strong>：如 &quot;Web 靶场 - SQL 注入&quot;</li><li><strong>镜像名称</strong>：Docker 镜像，如 <code>mysql:5.7</code></li><li><strong>端口映射</strong>：容器端口映射规则</li><li><strong>环境变量</strong>：容器环境变量（可选）</li><li><strong>启动命令</strong>：容器启动命令（可选）</li></ul></li><li>点击&quot;提交&quot;保存</li></ol><h4 id="端口映射配置" tabindex="-1">端口映射配置 <a class="header-anchor" href="#端口映射配置" aria-label="Permalink to &quot;端口映射配置&quot;">​</a></h4><p>端口映射格式：<code>容器端口:协议</code></p><p>示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>80:http</span></span>
<span class="line"><span>3306:tcp</span></span></code></pre></div><p>系统会自动为每个用户分配随机的宿主机端口。</p><h3 id="关联题目与容器" tabindex="-1">关联题目与容器 <a class="header-anchor" href="#关联题目与容器" aria-label="Permalink to &quot;关联题目与容器&quot;">​</a></h3><ol><li>编辑题目</li><li>在&quot;容器配置&quot;部分，选择容器模板</li><li>配置容器参数： <ul><li><strong>生存时间</strong>：容器自动销毁时间（分钟）</li><li><strong>最大实例数</strong>：每个用户最多可启动的容器数量</li></ul></li><li>保存题目</li></ol><p>用户答题时，点击&quot;启动靶机&quot;按钮即可获得独立的靶机环境。</p><h3 id="容器实例管理" tabindex="-1">容器实例管理 <a class="header-anchor" href="#容器实例管理" aria-label="Permalink to &quot;容器实例管理&quot;">​</a></h3><ol><li>进入 <strong>虚拟化管理</strong> → <strong>容器实例</strong></li><li>可以查看所有运行中的容器实例</li><li>支持的操作： <ul><li><strong>查看日志</strong>：查看容器运行日志</li><li><strong>重启容器</strong>：重启容器实例</li><li><strong>停止容器</strong>：停止并删除容器</li></ul></li></ol><h2 id="漏洞复现" tabindex="-1">漏洞复现 <a class="header-anchor" href="#漏洞复现" aria-label="Permalink to &quot;漏洞复现&quot;">​</a></h2><h3 id="vulhub-题库" tabindex="-1">Vulhub 题库 <a class="header-anchor" href="#vulhub-题库" aria-label="Permalink to &quot;Vulhub 题库&quot;">​</a></h3><p>CloudCTF 内置了 Vulhub 漏洞复现环境题库，可以一键导入真实漏洞环境。</p><p><img src="`+e+'" alt="漏洞复现环境列表"></p><h4 id="同步-vulhub-题库" tabindex="-1">同步 Vulhub 题库 <a class="header-anchor" href="#同步-vulhub-题库" aria-label="Permalink to &quot;同步 Vulhub 题库&quot;">​</a></h4><ol><li>进入 <strong>漏洞复现</strong> → <strong>漏洞环境</strong></li><li>点击&quot;同步漏洞模板&quot;按钮</li><li>系统会自动从 GitHub 拉取最新的 Vulhub 题库</li><li>等待同步完成</li></ol><div class="tip custom-block"><p class="custom-block-title">提示</p><p>同步可能需要几分钟时间，请耐心等待。</p></div><h3 id="自定义漏洞环境" tabindex="-1">自定义漏洞环境 <a class="header-anchor" href="#自定义漏洞环境" aria-label="Permalink to &quot;自定义漏洞环境&quot;">​</a></h3><p>除了 Vulhub 题库，你也可以创建自定义的漏洞环境：</p><ol><li>准备环境模板所需的 <code>docker-compose.yml</code> 或镜像/脚本</li><li>在后台创建容器模板，配置多服务编排</li><li>将模板关联到题目或漏洞环境</li></ol><h2 id="虚拟化" tabindex="-1">虚拟化 <a class="header-anchor" href="#虚拟化" aria-label="Permalink to &quot;虚拟化&quot;">​</a></h2><p>平台的 <strong>动态靶场</strong> 与 <strong>漏洞复现</strong> 功能依赖虚拟化能力。首次部署并登录管理后台后，建议优先完成虚拟化相关配置，避免后续创建题目或导入漏洞环境时出现容器无法启动等问题。</p><h3 id="主机类型与环境类型" tabindex="-1">主机类型与环境类型 <a class="header-anchor" href="#主机类型与环境类型" aria-label="Permalink to &quot;主机类型与环境类型&quot;">​</a></h3><p>虚拟化管理包含两层概念：</p><ul><li><strong>主机类型</strong>：环境实际运行的宿主资源来源。平台支持多种主机类型，用于承载不同环境： <ul><li><strong>Docker</strong>：适用于容器化环境（最常用）</li><li><strong>PVE（Proxmox VE）</strong>：适用于需要虚拟机隔离的场景（例如更强隔离/更贴近真实系统环境）</li></ul></li><li><strong>环境类型</strong>：题目/模板所使用的运行形态。 <ul><li><strong>静态环境</strong>：不启动容器，直接在题目中配置 Flag 与附件</li><li><strong>容器化环境</strong>：基于模板启动容器（动态靶场、漏洞复现等都属于此类）</li></ul></li></ul><p>不同主机类型常见差异（以页面字段为准）：</p><ul><li><strong>Docker 主机</strong>： <ul><li><code>endpoint</code> 通常为 Docker API 地址（例如 <code>unix:///var/run/docker.sock</code> 或 <code>tcp://host:2375</code>）</li><li><code>out_ip</code> 用于生成题目对外访问地址（非常关键）</li></ul></li><li><strong>PVE 主机</strong>： <ul><li><code>endpoint</code> 通常为 PVE API 地址（例如 <code>https://host:8006</code>）</li><li>通常需要配置 <code>username/password</code> 或 <code>api_key</code> 用于鉴权</li></ul></li></ul><h3 id="docker-compose-多服务编排" tabindex="-1">Docker Compose（多服务编排） <a class="header-anchor" href="#docker-compose-多服务编排" aria-label="Permalink to &quot;Docker Compose（多服务编排）&quot;">​</a></h3><p>平台支持将 <code>docker-compose.yml</code> 作为模板来源，用于一键启动多服务环境（例如 Web + DB + Cache）。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>这里的 <code>docker-compose.yml</code> 是 <strong>题目模板文件</strong>，不是平台主服务部署文件。<br> 当前 CloudCTF 主服务不再提供“下载 <code>docker-compose</code> 后一键启动整个平台”的官方部署方式。</p></div><p>使用 Compose 模板时建议关注：</p><ul><li><strong>入口服务</strong>：确定参赛者访问的入口服务（通常是 Web 服务）以及其对外端口</li><li><strong>端口声明</strong>：Compose 中的 <code>ports</code> 用于识别可访问端口；对外端口仍由平台在主机端口范围内自动分配</li><li><strong>资源声明</strong>：可在 Compose 服务中声明 CPU/内存需求（平台会按主机默认/上限裁剪）</li><li><strong>网络与依赖</strong>：多服务需要正确的网络互联与依赖顺序（按 Compose 配置为准）</li></ul><div class="tip custom-block"><p class="custom-block-title">提示</p><p>无论是 CTF 练兵场的容器化题目，还是漏洞复现的漏洞环境，本质上都会落到“容器化环境 + 主机节点”上。</p></div><h3 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li><strong>Docker 环境</strong>：确保后端所在机器已安装 Docker，并且 Docker 服务正常运行</li><li><strong>权限</strong>：后端进程需要具备访问 Docker 的权限（容器化部署时通常需要挂载 <code>/var/run/docker.sock</code>）</li><li><strong>网络连通性</strong>：后端可拉取镜像（能访问 Docker Hub 或自建镜像仓库）</li></ul><h3 id="配置主机节点" tabindex="-1">配置主机节点 <a class="header-anchor" href="#配置主机节点" aria-label="Permalink to &quot;配置主机节点&quot;">​</a></h3><ol><li>进入 <strong>虚拟化管理</strong> → <strong>主机管理</strong></li><li>点击&quot;新增主机&quot;</li><li>填写主机信息（按页面提示配置即可）</li><li>保存后在列表中查看主机状态是否为&quot;在线/可用&quot;</li></ol><div class="tip custom-block"><p class="custom-block-title">提示</p><p>如果你的部署是单机模式，通常只需要添加当前后端所在机器作为主机节点即可。</p></div><h3 id="出口配置-重要" tabindex="-1">出口配置（重要） <a class="header-anchor" href="#出口配置-重要" aria-label="Permalink to &quot;出口配置（重要）&quot;">​</a></h3><p>“出口配置”用于控制容器环境对外提供服务时的访问方式，常见场景包括：</p><ul><li>选手访问题目环境的 Web 服务</li><li>容器环境需要对外暴露端口（HTTP/HTTPS/TCP）</li><li>平台部署在反向代理/NAT 之后，需要正确生成访问地址</li></ul><p>建议在虚拟化主机或全局配置中明确：</p><ul><li><strong>对外域名/访问入口</strong>：对外访问使用的域名（例如 <code>https://ctf.example.com</code>）</li><li><strong>端口映射范围</strong>：宿主机用于分配给容器的端口段</li><li><strong>访问协议</strong>：HTTP/HTTPS（若走 HTTPS，证书通常由外部网关/反向代理负责）</li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p>如果出口配置不正确，常见现象是“容器已启动但访问地址打不开 / 地址生成错误 / 端口被占用”。</p></div><h3 id="资源限制" tabindex="-1">资源限制 <a class="header-anchor" href="#资源限制" aria-label="Permalink to &quot;资源限制&quot;">​</a></h3><p>为避免单个题目占用过多资源影响整个平台，建议为主机设置资源上限与默认值：</p><ul><li><strong>主机总资源</strong>：总内存（MB）、总 CPU（核数）、最大容器数量</li><li><strong>端口范围</strong>：端口范围起始/结束（用于自动分配对外端口）</li><li><strong>单容器默认资源</strong>：默认内存（MB）、默认 CPU（核数）</li><li><strong>单容器最大资源</strong>：最大内存（MB）、最大 CPU（核数）</li><li><strong>容器生命周期</strong>：默认存活时间（TTL，秒）、最大 TTL</li></ul><div class="tip custom-block"><p class="custom-block-title">提示</p><p>平台会根据“服务在模板中声明的资源”与“主机配置默认/最大值”综合计算容器最终限制，避免超额。</p></div><h3 id="模板资源" tabindex="-1">模板资源 <a class="header-anchor" href="#模板资源" aria-label="Permalink to &quot;模板资源&quot;">​</a></h3><p>容器模板可为每个服务声明资源需求（如 CPU/内存）。一般优先级为：</p><ol><li><strong>模板内服务声明的资源</strong>（如果有）</li><li><strong>主机默认资源</strong></li><li><strong>平台兜底默认值</strong></li></ol><p>当模板请求资源超过主机允许的最大值时，会自动按主机上限进行限制。</p><h3 id="运行时" tabindex="-1">运行时 <a class="header-anchor" href="#运行时" aria-label="Permalink to &quot;运行时&quot;">​</a></h3><p>运行时指容器真正启动与运行阶段的行为与运维能力，常见关注点包括：</p><ul><li><strong>启动与销毁</strong>：按 TTL 自动销毁过期容器，减少资源占用</li><li><strong>日志查看</strong>：通过容器实例查看运行日志定位错误</li><li><strong>重启/停止</strong>：必要时手动重启或停止实例（谨慎操作）</li><li><strong>容量规划</strong>：通过资源限制与最大容器数控制平台承载能力</li></ul><h3 id="镜像拉取与仓库设置" tabindex="-1">镜像拉取与仓库设置 <a class="header-anchor" href="#镜像拉取与仓库设置" aria-label="Permalink to &quot;镜像拉取与仓库设置&quot;">​</a></h3><ul><li><strong>公共镜像</strong>：默认从 Docker Hub 拉取（需要网络可访问）</li><li><strong>私有仓库</strong>：如使用私有镜像仓库，请在部署侧配置好登录凭据或镜像加速</li></ul><h3 id="连通性与权限检查" tabindex="-1">连通性与权限检查 <a class="header-anchor" href="#连通性与权限检查" aria-label="Permalink to &quot;连通性与权限检查&quot;">​</a></h3><p>完成主机配置后，建议做一次快速验证：</p><ul><li><strong>能否创建容器</strong>：后续在创建容器模板/漏洞环境模板时，能正常拉取镜像并启动容器</li><li><strong>日志可用</strong>：在 <strong>虚拟化管理</strong> → <strong>容器实例</strong> 中能查看日志</li><li><strong>端口映射正常</strong>：靶机启动后可正常访问分配的端口</li></ul><h2 id="管理员管理" tabindex="-1">管理员管理 <a class="header-anchor" href="#管理员管理" aria-label="Permalink to &quot;管理员管理&quot;">​</a></h2><p>管理员账号本质上也是用户账号，但管理员权限与平台功能绑定更紧密，建议单独按&quot;管理员管理&quot;流程进行配置。</p><h3 id="创建管理员" tabindex="-1">创建管理员 <a class="header-anchor" href="#创建管理员" aria-label="Permalink to &quot;创建管理员&quot;">​</a></h3><ol><li>进入 <strong>管理员管理</strong> → <strong>管理员列表</strong></li><li>点击&quot;新建管理员&quot;（或在用户列表中选中用户后提升权限，具体以页面为准）</li><li>为管理员分配角色</li><li>保存后使用该账号登录管理后台</li></ol><div class="tip custom-block"><p class="custom-block-title">提示</p><p>权限控制以&quot;角色&quot;为核心。不同角色对应不同管理能力；超级管理员可管理角色与权限。</p></div><h3 id="角色管理" tabindex="-1">角色管理 <a class="header-anchor" href="#角色管理" aria-label="Permalink to &quot;角色管理&quot;">​</a></h3><p>进入 <strong>管理员管理</strong> → <strong>角色管理</strong> 查看与维护角色。</p><p>系统内置角色（不可随意删除/修改）通常包括：</p><ul><li><strong>superadmin（超级管理员）</strong>：拥有全部管理权限，可管理用户、角色、比赛、题目、队伍等</li><li><strong>admin（管理员）</strong>：可管理比赛、题目、队伍等日常运营能力</li><li><strong>tenant（租户管理员）</strong>：通常用于多租户场景，偏向&quot;管理自己创建的比赛&quot;与题目维护</li><li><strong>player（选手）</strong>：普通参赛角色，仅具备参与比赛相关权限</li></ul><div class="tip custom-block"><p class="custom-block-title">提示</p><p>如需更细粒度的权限控制，可以创建自定义角色并分配权限（仅超级管理员可创建/修改/删除角色）。</p></div><h2 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to &quot;系统设置&quot;">​</a></h2><h3 id="基础配置" tabindex="-1">基础配置 <a class="header-anchor" href="#基础配置" aria-label="Permalink to &quot;基础配置&quot;">​</a></h3><ol><li>进入 <strong>系统管理</strong> → <strong>系统配置</strong></li><li>配置平台基础信息： <ul><li><strong>平台名称</strong>：显示在页面标题</li><li><strong>平台 Logo</strong>：上传平台 Logo</li><li><strong>平台描述</strong>：首页显示的描述文字</li><li><strong>联系邮箱</strong>：技术支持邮箱</li></ul></li></ol><h3 id="flag-配置" tabindex="-1">Flag 配置 <a class="header-anchor" href="#flag-配置" aria-label="Permalink to &quot;Flag 配置&quot;">​</a></h3><p>配置 Flag 格式：</p><ul><li><strong>Flag 前缀</strong>：默认 <code>flag{</code></li><li><strong>Flag 后缀</strong>：默认 <code>}</code></li><li><strong>Flag 长度</strong>：动态 Flag 的随机字符串长度</li></ul><h3 id="邮件配置" tabindex="-1">邮件配置 <a class="header-anchor" href="#邮件配置" aria-label="Permalink to &quot;邮件配置&quot;">​</a></h3><p>配置 SMTP 邮件服务，用于发送注册验证、密码重置等邮件：</p><ol><li>进入 <strong>系统管理</strong> → <strong>邮件配置</strong></li><li>填写 SMTP 信息： <ul><li><strong>SMTP 服务器</strong>：如 <code>smtp.gmail.com</code></li><li><strong>SMTP 端口</strong>：如 <code>587</code></li><li><strong>发件人邮箱</strong>：如 <code>noreply@example.com</code></li><li><strong>SMTP 密码</strong>：邮箱密码或授权码</li></ul></li><li>点击&quot;测试连接&quot;验证配置</li><li>保存配置</li></ol><h2 id="备份与恢复" tabindex="-1">备份与恢复 <a class="header-anchor" href="#备份与恢复" aria-label="Permalink to &quot;备份与恢复&quot;">​</a></h2><p>平台提供后台内置备份能力，建议将其作为日常备份手段，并配合运维侧的数据库与文件备份形成完整灾备方案。</p><h3 id="内置备份入口" tabindex="-1">内置备份入口 <a class="header-anchor" href="#内置备份入口" aria-label="Permalink to &quot;内置备份入口&quot;">​</a></h3><p>进入 <strong>系统设置</strong> → <strong>备份与恢复</strong>（或直接访问 <code>/admin/settings</code>，以页面为准）。</p><h3 id="创建备份" tabindex="-1">创建备份 <a class="header-anchor" href="#创建备份" aria-label="Permalink to &quot;创建备份&quot;">​</a></h3><ol><li>进入备份页面</li><li>点击&quot;创建备份&quot;</li><li>等待备份完成后，在备份列表中查看新生成的备份</li></ol><h3 id="下载备份" tabindex="-1">下载备份 <a class="header-anchor" href="#下载备份" aria-label="Permalink to &quot;下载备份&quot;">​</a></h3><p>建议将备份下载并保存到本地或对象存储，避免仅保存在服务器本机。</p><ol><li>在备份列表中选择目标备份</li><li>点击&quot;下载&quot;</li><li>保存 ZIP 文件并做好备份归档（建议按日期/版本号命名）</li></ol><h3 id="上传备份" tabindex="-1">上传备份 <a class="header-anchor" href="#上传备份" aria-label="Permalink to &quot;上传备份&quot;">​</a></h3><p>当需要跨服务器迁移或导入历史备份时，可以上传备份 ZIP 文件。</p><ol><li>点击&quot;上传备份&quot;</li><li>选择备份 ZIP 文件</li><li>上传成功后在备份列表中确认已出现对应备份记录</li></ol><h3 id="恢复备份" tabindex="-1">恢复备份 <a class="header-anchor" href="#恢复备份" aria-label="Permalink to &quot;恢复备份&quot;">​</a></h3><p>恢复会覆盖现有数据，建议在低峰期执行，并提前做好兜底备份。</p><ol><li>在备份列表中选择目标备份</li><li>点击&quot;恢复&quot;</li><li>按页面提示确认恢复操作</li><li>恢复完成后验证：登录、比赛/题目、容器化题目启动等关键功能</li></ol><div class="warning custom-block"><p class="custom-block-title">注意</p><p>内置备份更适合平台级配置与业务数据的快速备份与迁移。对生产环境，仍建议保留 MySQL（<code>mysqldump</code>）或 PostgreSQL（<code>pg_dump</code>）与 uploads 的独立备份，以应对更严重的灾难场景。</p></div><p>更多运维侧的备份与恢复建议请参考：<a href="/CloudCTF/guide/admin-guide.html#备份与恢复">备份与恢复</a></p><h2 id="数据统计" tabindex="-1">数据统计 <a class="header-anchor" href="#数据统计" aria-label="Permalink to &quot;数据统计&quot;">​</a></h2><h3 id="平台概览" tabindex="-1">平台概览 <a class="header-anchor" href="#平台概览" aria-label="Permalink to &quot;平台概览&quot;">​</a></h3><ol><li>进入 <strong>仪表盘</strong></li><li>查看平台统计数据： <ul><li><strong>用户总数</strong>：注册用户数量</li><li><strong>题目总数</strong>：平台题目数量</li><li><strong>比赛总数</strong>：已创建的比赛数量</li><li><strong>提交总数</strong>：Flag 提交次数</li></ul></li></ol><h3 id="用户活跃度" tabindex="-1">用户活跃度 <a class="header-anchor" href="#用户活跃度" aria-label="Permalink to &quot;用户活跃度&quot;">​</a></h3><p>查看用户活跃度统计：</p><ul><li><strong>日活跃用户</strong>：每日登录用户数</li><li><strong>解题趋势</strong>：每日解题数量</li><li><strong>热门题目</strong>：解题人数最多的题目</li></ul><h3 id="导出数据" tabindex="-1">导出数据 <a class="header-anchor" href="#导出数据" aria-label="Permalink to &quot;导出数据&quot;">​</a></h3><p>支持导出以下数据：</p><ul><li><strong>用户列表</strong>：导出所有用户信息</li><li><strong>题目列表</strong>：导出所有题目信息</li><li><strong>比赛数据</strong>：导出比赛排行榜和提交记录</li></ul><h2 id="安全建议" tabindex="-1">安全建议 <a class="header-anchor" href="#安全建议" aria-label="Permalink to &quot;安全建议&quot;">​</a></h2><h3 id="账号安全" tabindex="-1">账号安全 <a class="header-anchor" href="#账号安全" aria-label="Permalink to &quot;账号安全&quot;">​</a></h3><ol><li>✅ 修改默认管理员密码</li><li>✅ 定期更换密码</li><li>✅ 不要共享管理员账号</li></ol><h3 id="平台安全" tabindex="-1">平台安全 <a class="header-anchor" href="#平台安全" aria-label="Permalink to &quot;平台安全&quot;">​</a></h3><ol><li>✅ 定期备份数据库</li><li>✅ 监控容器资源使用</li><li>✅ 限制容器生存时间</li><li>✅ 定期清理过期容器</li><li>✅ 配置防火墙规则</li><li>✅ 使用 HTTPS</li></ol><h3 id="题目安全" tabindex="-1">题目安全 <a class="header-anchor" href="#题目安全" aria-label="Permalink to &quot;题目安全&quot;">​</a></h3><ol><li>✅ 使用动态 Flag 防止作弊</li><li>✅ 限制 Flag 提交频率</li><li>✅ 记录所有提交日志</li><li>✅ 监控异常提交行为</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="如何批量导入题目" tabindex="-1">如何批量导入题目？ <a class="header-anchor" href="#如何批量导入题目" aria-label="Permalink to &quot;如何批量导入题目？&quot;">​</a></h3><p>目前支持通过 Vulhub 题库批量导入漏洞环境题目。如需导入自定义题目，建议使用 API 接口批量创建。</p><h3 id="容器启动失败怎么办" tabindex="-1">容器启动失败怎么办？ <a class="header-anchor" href="#容器启动失败怎么办" aria-label="Permalink to &quot;容器启动失败怎么办？&quot;">​</a></h3><ol><li>检查 Docker 服务是否正常运行</li><li>查看容器日志，定位错误原因</li><li>检查镜像是否存在</li><li>确认端口映射配置正确</li></ol><h3 id="如何限制用户提交频率" tabindex="-1">如何限制用户提交频率？ <a class="header-anchor" href="#如何限制用户提交频率" aria-label="Permalink to &quot;如何限制用户提交频率？&quot;">​</a></h3><p>在系统配置中，可以设置 Flag 提交间隔时间，防止暴力破解。</p><h2 id="获取帮助" tabindex="-1">获取帮助 <a class="header-anchor" href="#获取帮助" aria-label="Permalink to &quot;获取帮助&quot;">​</a></h2><p>如果遇到问题，可以：</p><ol><li>查看 <a href="/CloudCTF/guide/faq.html">常见问题</a></li><li>查看 <a href="/CloudCTF/api/overview.html">API 文档</a></li><li>提交 <a href="https://github.com/hexbay/CloudCTF/issues" target="_blank" rel="noreferrer">GitHub Issue</a></li><li>联系技术支持: <a href="mailto:5829662@qq.com" target="_blank" rel="noreferrer">5829662@qq.com</a></li></ol>',235)])])}const b=o(s,[["render",n]]);export{q as __pageData,b as default};
